'use strict';
const $=s=>document.querySelector(s),U=TX.u,S=TX.state;
const names={overview:'Study overview',maps:'Lexical maps',reading:'Readings & Q&A',storage:'Contexts & storage',methods:'Sources & methods'};
function scope(){
 if(['storage','methods'].includes(S.view)){document.getElementById('scope').hidden=true;return}
 const all=TX.data.analysis.sources.filter(d=>d.modality===(S.corpus==='audio'?'audio_asr':'publisher_text')),docs=TX.currentDocs();
 document.getElementById('scope').hidden=false;
 document.getElementById('scope').innerHTML=`<form id="scope-form" class="scope-form"><label>Fitted corpus<select name="corpus">${U.option('audio','Audio ASR · 20 documents',S.corpus)}${U.option('authored','Publisher text · 16 documents',S.corpus)}</select></label><label>Publisher<select name="publisher">${U.option('all','All publishers',S.publisher)}${[...new Set(all.map(d=>d.publisher))].sort().map(x=>U.option(x,x,S.publisher)).join('')}</select></label><label>Practitioner context<select name="context">${U.option('all','All source contexts',S.context)}${[...new Set(all.map(d=>d.practitionerContext))].sort().map(x=>U.option(x,x,S.context)).join('')}</select></label><label>Source title, publisher or ID<input type="search" name="query" value="${U.esc(S.query)}" placeholder="Search source metadata"></label><button type="submit">Apply source filters</button></form><p class="scope-summary"><strong>${U.num(docs.length)} / ${U.num(all.length)} ${S.corpus==='audio'?'ASR documents':'publisher texts'}</strong> in this view. ${S.corpus==='audio'?'The full ASR frame is 19 Bashar-context recordings and one Ashtar-attributed creator episode; not 20 mediums.':'Fifteen Daniel Scranton RSS posts and one Paul Selig publisher transcript. Authored and ASR models are fitted separately.'} Filtering selects retained vectors; it does not refit the model.</p>`;
}
function summaryStrip(items){return `<div class="summary-strip">${items.map(([v,l])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`}
function corpusNotice(){return `<div class="notice"><strong>Separate sources, separate models</strong>Audio ASR and authored publisher text use separate TF-IDF, topic and clustering fits. Topic numbers have meaning only within their fitted corpus. Source labels and text mentions do not verify speakers, civilizations or origins.</div>`}
function overview(){
 const a=TX.data.analysis,docs=TX.docs(),tokens=docs.reduce((n,d)=>n+d.tokenCount,0),hours=docs.reduce((n,d)=>n+(d.durationSeconds||0),0)/3600,pubs=[...new Set(docs.map(d=>d.publisher))].length;
 if(!docs.length)return U.heading('Retained source selection','No source documents match','This is an empty filtered selection, not a measured absence of themes or questions.')+`<button data-action="reset-source-filters">Reset source filters</button>`;
 const topic=TX.topics(),topicRows=topic.terms.map((t,i)=>({label:`T${i+1}: ${t.label}`,value:docs.length?topic.weights.filter(w=>docs.some(d=>d.sourceId===w.sourceId)).reduce((n,r)=>n+r.weights[i],0)/docs.length:0}));
 const byContext=[...new Set(docs.map(d=>d.claimedGroup))].map(label=>({label,value:docs.filter(d=>d.claimedGroup===label).length}));
 return U.heading('Retained text · exploratory analysis','A source-aware transcript study','Explore full-audio machine-ASR outputs and publisher-authored comparisons through lexical maps, sampled AI readings and inspectable source metadata. No source here establishes an extraterrestrial origin.')+`<p>${U.artifact('paper.pdf','New transcript-study paper PDF')} · ${U.artifact('source.zip','Portable manuscript source ZIP')}</p>`+
 summaryStrip([[U.num(docs.length),`${S.corpus==='audio'?'Audio ASR':'Authored'} documents selected`],[U.num(tokens),'Common analytical tokens'],[S.corpus==='audio'?U.num(hours,2):U.num(pubs),S.corpus==='audio'?'Recorded audio hours':'Publisher groups in this selection'],['0','Saved YouTube videos']])+
 `<div class="two-col"><section><h2>Source contexts in the selection</h2>${TX.chart.bars(byContext,Math.max(1,docs.length))}<p class="caption">Counts are publication documents with catalog context labels. Hosts, guests, advertising and claimed-entity turns are not diarized.</p></section><section><h2>Three exploratory topic components</h2>${TX.chart.bars(topicRows,1)}<p class="caption">Equal-document mean NMF share, fixed 0–1 scale. K=${topic.selectedK} was a predeclared display choice, not an estimated true topic count. Labels are top terms, including possible transcription artifacts.</p><a href="#maps">Inspect document-level topics and lexical maps →</a></section></div>`+
 corpusNotice()+`<section class="section"><div class="section-head"><h2>What is measured</h2><p>All views preserve provenance and modality. Analytical token counts are distinct from historical acquisition receipt word counts.</p></div>${U.table(['Evidence layer','Available material','Interpretation'],[['Complete retained text','20 full-audio ASR documents; 16 publisher texts','Convenience sample; ASR is unverified and authored content includes promotion and footers.'],['Lexical models','Separate TF-IDF fits, NMF topic shares and exploratory clusters','Reproducible text representation, not semantic agreement or a speaker taxonomy.'],['AI source readings',TX.data.reading?.summary?'Sampled-window review metadata available':'Source reading results are not bound in this candidate yet','Paraphrases and candidate Q&A require source-window provenance; no human accuracy claim.'],['Storage and collection','Independent publisher audio and local derived files','Saved publisher audio is not a YouTube download; local storage is distinct from Drive.']])}</section>`+
 `<section class="section"><h2>Inspect the source selection</h2>${sourceTable(docs)}<button class="secondary" data-action="export-sources">Export these source metadata rows</button></section>`;
}
function sourceTable(docs){return U.table(['Source / publisher','Source context / format','Common tokens','Audio duration'],docs.map(d=>[U.sourceButton(d.sourceId,d.shortId+' · '+d.title)+`<small>${U.esc(d.publisher)}</small>`,U.esc(d.claimedGroup)+`<small>${U.esc(U.human(d.sourceFormat))}</small>`,U.num(d.tokenCount),d.durationSeconds==null?'Authored text':U.num(d.durationSeconds/60,1)+' min']))}
function mapControls(){const t=TX.topics();return `<div class="subnav" aria-label="Lexical visualization">${[['network','Similarity network'],['projection','Clusters & projection'],['topics','Topics & keywords'],['terms','TF-IDF terms'],['mentions','Claimed-label mentions'],['time','Time profiles']].map(([id,label])=>`<button type="button" data-map="${id}" aria-pressed="${S.map===id}">${label}</button>`).join('')}</div><form id="map-controls" class="toolbar">${['network','projection'].includes(S.map)?`<label>Node color<select name="color">${[['cluster','Exploratory cluster'],['topic','Dominant fitted topic'],['context','Practitioner context']].map(([v,l])=>U.option(v,l,S.color)).join('')}</select></label><label>Topic membership filter<select name="topic">${U.option('all','All fitted components',S.topic)}${t.terms.map((x,i)=>U.option(i,`Dominant T${i+1}: ${x.label}`,S.topic)).join('')}</select></label><label class="check"><input type="checkbox" name="labels"${S.labels?' checked':''}>Show source IDs</label>`:''}${S.map==='network'?`<label>Edge rule<select name="edgeRule">${U.option('nearest','Union of two nearest selected neighbors',S.edgeRule)}${U.option('all','All selected pairs above threshold',S.edgeRule)}</select></label><label>Minimum cosine <output id="threshold-output">${S.threshold.toFixed(2)}</output><input type="range" name="threshold" min="0" max="1" step="0.01" value="${S.threshold}"></label>`:''}${S.map==='projection'&&S.corpus==='audio'?`<label class="check"><input type="checkbox" name="overlay"${S.overlay?' checked':''}>Add authored texts in the ASR reference space</label>`:''}${S.map==='topics'?`<label>Heatmap rows<select name="heatGroup">${[['document','Publication document'],['publisher','Publisher mean'],['context','Practitioner-context mean']].map(([v,l])=>U.option(v,l,S.heatGroup)).join('')}</select></label>`:''}${S.map==='time'?`<label>Keyword family<select name="timeTheme">${Object.keys(TX.data.analysis.lexicons.themeDefinitions).map(k=>U.option(k,U.human(k),S.timeTheme||'contact_disclosure')).join('')}</select></label>`:''}</form>`}
function inspector(){const d=TX.source(S.selected),docs=TX.currentDocs(),reference=S.map==='projection'&&S.corpus==='audio'&&S.overlay&&TX.docs('authored').some(x=>x.sourceId===S.selected);if(!d||(!reference&&!docs.some(x=>x.sourceId===d.sourceId)))return `<aside class="inspector"><h3>Inspect a document</h3><p>Select a labeled node with a pointer or keyboard, or use the source table below.</p><p class="caption">Every node is one publication document. Narrow-screen node hit areas are enlarged; use source tables for overlapping projected points. Neither an edge nor a cluster identifies a speaking entity or validates a claim.</p></aside>`;const edges=S.map==='network'?TX.edges(docs).filter(e=>e.source===d.sourceId||e.target===d.sourceId):[];return `<aside class="inspector"><h3>${U.esc(d.shortId)} · ${U.esc(d.publisher)}</h3><p>${U.esc(d.title)}</p><p>${U.num(d.tokenCount)} common tokens · ${U.esc(d.claimedGroup)}</p><p>${reference?'Authored text projected into the ASR reference space; not a member of the ASR clusters or topic fit.':S.map==='projection'?'Source coordinates in the named fit; no similarity edges are drawn in this projection.':`${edges.length} adjacent edges under this display rule.`}</p>${edges.slice(0,5).map(e=>{const o=TX.source(e.source===d.sourceId?e.target:e.source);return `<p>${U.esc(o.shortId)} · cosine ${U.num(e.cosine,3)}</p>`}).join('')}<button data-source="${U.esc(d.sourceId)}" class="secondary">Inspect provenance</button></aside>`}
function maps(){
 const docs=TX.currentDocs(),c=TX.clusters(),isProjection=S.map==='projection';let content='';
 if(['network','projection'].includes(S.map)){content=`<div class="plot-layout">${TX.chart.network(isProjection)}${inspector()}</div><div class="legend">${TX.chart.legend(docs)}</div><p class="caption">${isProjection?`${U.esc(c.projection.method)}. The two components retain ${U.percent(c.projection.explainedVarianceRatio.reduce((n,v)=>n+v,0))} of fitted variance. ${S.corpus==='audio'&&S.overlay?'Square authored markers are transformed through the ASR vocabulary/IDF/SVD, not pooled or clustered with ASR. The dominant-topic filter affects only the ASR core; reference texts are not assigned ASR topic IDs.':''} Two-dimensional distance is a lossy lexical display. Source tables and zoom provide alternatives when points or labels overlap on narrow screens.`:`Circular positions are schematic; equal node sizes mean one source document. ${S.edgeRule==='nearest'?'Each selected document contributes up to two nearest selected neighbors above the threshold.':'Every selected pair above the threshold is shown.'} Cosine ≥ ${S.threshold.toFixed(2)}. An edge is lexical resemblance, not agreement, social connection or independent transmission.`}</p><p class="caption">KMeans display: k=${c.selectedK}, selected by the highest candidate cosine silhouette. ${U.esc(c.silhouetteInterpretation||'Clusters are exploratory, not validated classes.')} ${S.corpus==='audio'?'The 19:1 source-context imbalance and singleton episode can dominate this partition.':''}</p>${docs.length&&!TX.edges(docs).length&&!isProjection?'<p class="empty">No pair passes this edge rule and threshold. Source nodes remain visible; lower the threshold or reset filters to explore other pairs.</p>':''}<details><summary>Inspect exact displayed pair data</summary>${U.table(['Source A','Source B','TF-IDF cosine'],TX.edges(docs).map(e=>[U.sourceButton(e.source,TX.source(e.source).shortId),U.sourceButton(e.target,TX.source(e.target).shortId),U.num(e.cosine,5)]))}<button data-action="export-edges" class="secondary">Export displayed pairs</button></details>`}
 else if(S.map==='topics')content=topicView(docs);
 else if(S.map==='terms')content=termView(docs);
 else if(S.map==='mentions')content=`<h2>Dictionary-family co-mentions</h2><p class="lede">${docs.length} selected documents. Counts are exact dictionary matches; a shared star-system word can refer to astronomy, fiction or ASR error. Edges count documents containing both families.</p>${TX.chart.entity()}<h3>Named entity strings are a separate dictionary</h3>${entityNameTable(docs)}<p class="caption">Bashar and Ashtar names are not silently assigned to a civilization family. Publisher-declared inventory labels are a separate source layer in Contexts &amp; storage.</p>`;
 else content=timeView(docs);
 return U.heading('Fixed lexical fits · interactive source selection','Text relationships you can inspect','Similarity, topic and clustering views describe retained text. They do not compare the truth of claims or independently identify mediums or civilizations.')+mapControls()+`<p class="caption fit-scope"><strong>Active model: ${S.corpus==='audio'?'20-document ASR fit':'16-document authored-text fit'}.</strong> ${docs.length} source documents selected. Topic IDs, cluster labels and cosine values remain scoped to this fit.</p>`+content+`<section class="section"><h2>Documents behind this view</h2>${sourceTable(docs)}${S.map==='projection'&&S.corpus==='audio'&&S.overlay?`<h3>Authored reference projections (separate modality)</h3>${sourceTable(TX.docs('authored'))}`:''}<button class="secondary" data-action="export-sources">Export the shown core/reference source metadata</button></section>`;
}
function topicView(docs){
 const t=TX.topics(),map=new Map(t.weights.map(w=>[w.sourceId,w.weights]));let rows;
 if(S.heatGroup==='document')rows=docs.map(d=>({label:d.shortId+' · '+d.publisher,sourceId:d.sourceId,values:map.get(d.sourceId)}));
 else {const prop=S.heatGroup==='publisher'?'publisher':'practitionerContext';rows=[...new Set(docs.map(d=>d[prop]))].sort().map(label=>{const ds=docs.filter(d=>d[prop]===label);return{label:label+` (n=${ds.length})`,values:t.terms.map((_,i)=>ds.reduce((n,d)=>n+map.get(d.sourceId)[i],0)/ds.length)}})}
 const rates=TX.data.analysis.lexicons.themeRates,themeKeys=Object.keys(TX.data.analysis.lexicons.themeDefinitions),lexrows=docs.map(d=>({sourceId:d.sourceId,label:d.shortId+' · '+d.publisher,values:themeKeys.map(k=>rates.find(r=>r.sourceId===d.sourceId)?.rates[k]??null)}));const max=Math.max(1,...lexrows.flatMap(r=>r.values.filter(v=>v!=null)));
 return `<h2>Document-topic shares</h2><p class="caption">${S.corpus==='audio'?'ASR':'Authored'} NMF k=${t.selectedK}. ${U.esc(t.selectedKMeaning)}. Document shares sum to 1. Group rows average documents equally; the same 0–100% color scale applies to every cell.</p>${TX.chart.heat(t.terms.map((x,i)=>`T${i+1}: ${x.label}`),rows)}<details><summary>Inspect top terms and topic diagnostics</summary>${U.table(['Component','Top terms'],t.terms.map((t,i)=>[`T${i+1}`,t.terms.map(w=>U.esc(w.term)+' ('+U.num(w.weight,3)+')').join(', ')]))}${U.table(['Candidate k','Reconstruction error','Seed-matched term cosine'],t.candidates.map(x=>[U.num(x.k),U.num(x.reconstructionError,3),U.num(x.matchedTopicCosineMean,3)]))}<p class="caption">Reconstruction error and seed stability do not validate topic meaning.</p></details><section class="section"><h2>Predeclared keyword-family rates</h2><p class="caption">Pattern occurrences per 1,000 common analytical tokens. Families overlap; zero is retained. Every cell shares a 0–${U.num(max,2)} scale, not a different scale for each row.</p>${TX.chart.heat(themeKeys.map(U.human),lexrows,{max,unit:'rate'})}<details><summary>Inspect keyword extraction patterns</summary>${U.table(['Family','Exact regex patterns'],themeKeys.map(k=>[U.esc(U.human(k)),`<code>${U.esc(TX.data.analysis.lexicons.themeDefinitions[k].join(' | '))}</code>`]))}</details></section>`;
}
function termRows(docs){const f=TX.fit(),matrix=f.displayTermWeights;if(!matrix)return f.terms.map(x=>({...x,scope:'full_fit'}));return f.terms.map((t,i)=>({term:t.term,weight:docs.length?matrix.filter(r=>docs.some(d=>d.sourceId===r.sourceId)).reduce((n,r)=>n+r.weights[i],0)/docs.length:0,scope:'selected_documents_fixed_display_vocabulary'})).sort((a,b)=>b.weight-a.weight||a.term.localeCompare(b.term))}
function termView(docs){if(!docs.length)return U.empty('No selected source documents: a mean TF-IDF weight is undefined, not zero. Reset the source filters to restore the fitted corpus.');const f=TX.fit(),rows=termRows(docs);return `<h2>Mean TF-IDF weights</h2><p class="caption">${f.displayTermWeights?'Exact equal-document means for the selected sources':'Full-fit means; source filters do not recompute this older candidate output'}. Ranking is restricted to the fixed 40-term display vocabulary chosen from the full ${S.corpus} fit (${U.num(f.featureCount)} fitted features). Weight is not a raw word count or validated concept importance.</p>${TX.chart.bars(rows.slice(0,20).map(r=>({label:r.term,value:r.weight,digits:4})))}<button class="secondary" data-action="export-terms">Export these ranked term weights</button>${U.table(['Displayed term','Mean TF-IDF weight'],rows.map(r=>[U.esc(r.term),U.num(r.weight,6)]))}`}
function entityNameTable(docs){const x=TX.data.analysis.lexicons,rows=x.entityNameCounts.filter(r=>docs.some(d=>d.sourceId===r.sourceId));return U.table(['Entity-name string family','Documents with ≥1 match','Matches'],Object.keys(x.entityNameDefinitions).map(k=>[U.esc(k),U.num(rows.filter(r=>r.counts[k]>0).length),U.num(rows.reduce((n,r)=>n+(r.counts[k]||0),0))]))}
function timeView(docs){
 if(S.corpus!=='audio')return U.empty('Decoded-audio time profiles apply only to the ASR corpus. Switch to Audio ASR to inspect ten-bin trajectories; authored texts have no verified audiovisual timeline.');
 if(!docs.length)return U.empty('No ASR documents match the source filters. No time-bin rates are estimated for an empty selection.');
 const theme=S.timeTheme||'contact_disclosure',profiles=TX.data.analysis.lexicons.timeProfiles,groups=[...new Set(docs.map(d=>d.practitionerContext))].map(label=>{const ds=docs.filter(d=>d.practitionerContext===label);return{label,n:ds.length,values:Array.from({length:10},(_,i)=>{const vals=ds.map(d=>profiles.find(p=>p.sourceId===d.sourceId)?.bins[i]?.rates[theme]).filter(v=>v!=null);return vals.length?vals.reduce((n,v)=>n+v,0)/vals.length:null})}}),max=Math.max(1,...groups.flatMap(g=>g.values.filter(v=>v!=null))),colors=TX.chart.colors;
 return `<h2>${U.esc(U.human(theme))} across decoded-audio time</h2><div class="plot-area"><svg viewBox="0 0 900 390" role="img" aria-label="Equal-document keyword rates in ten normalized audio-time bins"><line x1="70" y1="320" x2="840" y2="320" stroke="#6b737b"/><line x1="70" y1="40" x2="70" y2="320" stroke="#6b737b"/>${[0,.25,.5,.75,1].map(f=>`<text x="60" y="${324-f*280}" text-anchor="end">${U.num(max*f,1)}</text><line x1="70" y1="${320-f*280}" x2="840" y2="${320-f*280}" stroke="#ccd3c8"/>`).join('')}${Array.from({length:10},(_,i)=>`<text x="${70+i/9*770}" y="347" text-anchor="middle">${i*10+5}%</text>`).join('')}${groups.map((g,k)=>`<polyline fill="none" stroke="${colors[k]}" stroke-width="3" points="${g.values.map((v,i)=>v==null?'':`${70+i/9*770},${320-v/max*280}`).join(' ')}"/>${g.values.map((v,i)=>v==null?'':`<circle cx="${70+i/9*770}" cy="${320-v/max*280}" r="4" fill="${colors[k]}"><title>${U.esc(g.label)} bin${i+1}: ${U.num(v,3)}</title></circle>`).join('')}`).join('')}</svg></div><div class="legend">${groups.map((g,i)=>`<span><i style="background:${colors[i]}"></i>${U.esc(g.label)} · n=${g.n}</span>`).join('')}</div><p class="caption">Occurrences per 1,000 common tokens within each bin; equal-document group means on one shared y-scale. Segment midpoints assign ten equal decoded-audio-time bins. Bins are dependent; one Athina episode is not a population trajectory. Hosts, ads and outros remain unsegmented.</p>${U.table(['Source context',...Array.from({length:10},(_,i)=>`${i*10}–${i*10+10}%`)],groups.map(g=>[U.esc(g.label)+` (n=${g.n})`,...g.values.map(v=>v==null?'No tokens':U.num(v,2))]))}`;
}
function qaRecords(){const records=U.rows(TX.data.reading?.qa),ids=new Set(TX.docs().map(d=>d.sourceId));return records.filter(r=>ids.has(r.sourceId)&&(S.qaKind==='all'||r.candidateKind===S.qaKind)&&(S.qaFamily==='all'||r.promptFamily===S.qaFamily)&&(!S.qaQuery||[r.questionParaphrase,r.answerParaphrase,r.promptFamily].join(' ').toLowerCase().includes(S.qaQuery.toLowerCase())))}
function interpretiveFindings(){
 const rows=U.rows(TX.data.reading?.findings);if(!rows.length)return '';
 return `<section class="section" id="interpretive-findings"><h2>Six source-bound interpretive leads</h2><p class="caption">Whole-study comparisons retain both modalities and are not changed by the source filters above. Source filters apply to the syntheses and Q&A below. These are provisional AI interpretations, not human-validated findings or population estimates.</p><div class="qa-list">${rows.map(r=>`<article class="qa-item"><h3>${U.esc(r.label)}</h3><p>${U.esc(r.paraphrase)}</p><p>${(r.sourceIds||[]).map(id=>U.sourceButton(id,(TX.source(id)?.shortId||id)+' · '+(TX.source(id)?.publisher||''))).join(' · ')}</p><details><summary>Inspect source windows and interpretation status</summary><p>${U.esc(r.type)} · human validated: ${r.humanValidated?'yes':'no'}.</p><ul>${(r.supportWindowIds||[]).map(id=>`<li><code>${U.esc(id)}</code></li>`).join('')}</ul></details></article>`).join('')}</div></section>`;
}
function reading(){
 const r=TX.data.reading,docs=TX.docs();if(!r?.summary&&!r?.qa)return U.heading('Source-bound qualitative reading','Readings & Q&A candidates','AI source readings use sampled windows, paraphrases and exact metadata locators. They do not establish verified speaker turns.')+U.empty('Reading outputs are not bound in this candidate yet. Quantitative complete-text analysis and sampled-window qualitative review are separate workstreams.');
 const q=qaRecords(),all=U.rows(r.qa),families=[...new Set(all.map(x=>x.promptFamily))].sort(),kinds=[...new Set(all.map(x=>x.candidateKind))].sort(),pageCount=Math.max(1,Math.ceil(q.length/12));S.qaPage=Math.min(S.qaPage,pageCount);const shown=q.slice((S.qaPage-1)*12,S.qaPage*12),codes=U.rows(r.codes).filter(x=>docs.some(d=>d.sourceId===x.sourceId));
 return U.heading('AI sampled-window reading · not human validation','Readings and candidate questions','Source-linked paraphrases preserve the difference between interview prompts, rhetorical questions, secondary reports and analyst-constructed comparison prompts. Evidence windows are not verified question/answer turn boundaries.')+
 summaryStrip([[U.num(r.summary.inspectedWindows),'Whole-study inspected windows'],[U.num(r.summary.packetWordsRead),'Packet words, including overlapping windows'],[U.num(r.summary.qaCandidateRecords),'Whole-study Q&A / comparison candidates'],['0','Human-validated annotations']])+`<div class="notice"><strong>Review coverage is sampled</strong>${U.esc(r.summary.coverageDescription||r.summary.readingScope||'The reviewer inspected selected source windows. Full-text computational processing is distinct from human or AI close reading of every word.')} No speaker identity or human coding accuracy is established.</div>${U.table(['Whole-study sampled coverage','Unique whitespace words read / source total','Coverage'],[['Audio ASR',U.num(r.summary.uniqueAsrWordsRead)+' / '+U.num(r.summary.asrWordsTotal),U.percent(r.summary.asrWordCoverageFraction)],['Publisher texts',U.num(r.summary.uniquePublisherTextWordsRead)+' / '+U.num(r.summary.publisherTextWordsTotal),U.percent(r.summary.publisherTextWordCoverageFraction)]])}<p class="caption">Coverage above describes the whole reading workstream, not the filtered source subset. ${U.esc(r.summary.methods?.wordCountMethod)} Sampling is purposeful and keyword-enriched; code presence is not full-corpus theme prevalence.</p><details><summary>Inspect exact reading coverage metadata</summary><pre class="metadata-pre">${U.esc(JSON.stringify(r.summary,null,2))}</pre></details>`+
 interpretiveFindings()+`<section class="section"><div class="section-head"><h2>Source syntheses</h2><p>AI interpretations below are bound to sampled support windows and should be read with each source's format and perspective.</p></div>${codes.length?U.table(['Source / context','AI synthesis paraphrase','Codes / source perspective'],codes.map(c=>{const d=TX.source(c.sourceId);return[U.sourceButton(c.sourceId,(d?.shortId||c.sourceId)+' · '+(d?.publisher||'')),U.esc(c.synthesisParaphrase),U.esc((c.codes||[]).join(' · '))+`<small>${U.esc(c.narrativePosition||c.reviewStatus)}</small>`]})):U.empty('No source syntheses match this corpus and source filter.')}</section>`+
 `<section class="section"><h2>Candidate questions and answers</h2><form id="qa-filter" class="toolbar"><label>Candidate kind<select name="qaKind">${U.option('all','All kinds within this corpus',S.qaKind)}${kinds.map(k=>U.option(k,U.human(k),S.qaKind)).join('')}</select></label><label>AI prompt family<select name="qaFamily">${U.option('all','All families',S.qaFamily)}${families.map(k=>U.option(k,U.human(k),S.qaFamily)).join('')}</select></label><label>Search derived paraphrases<input type="search" name="qaQuery" value="${U.esc(S.qaQuery)}" placeholder="Question, answer gist or prompt family"></label><button type="submit">Filter candidates</button><button type="button" class="secondary" data-action="export-qa"${q.length?'':' disabled'}>Export filtered candidate metadata</button></form><p class="caption">${U.num(q.length)} matching candidates in ${U.num(docs.length)} selected source documents; ${U.num(all.length)} candidates in the full reading artifact. Question and answer wording is paraphrased, not a literal transcript quote.</p><div class="qa-list">${shown.map(x=>{const d=TX.source(x.sourceId);return `<article class="qa-item">${U.badge(x.candidateKind==='authored_comparison_prompt'?'Analyst-constructed authored comparison prompt':U.human(x.candidateKind))}<h3>${U.esc(x.questionParaphrase||'Question wording not recoverable in this window')}</h3><p class="answer">${U.esc(x.answerParaphrase||'No source-supported answer paraphrase recorded')}</p><p class="caption">${U.sourceButton(x.sourceId,(d?.shortId||x.sourceId)+' · '+(d?.publisher||''))}<br>Support window ${U.esc(x.supportWindowId||'not recorded')} · ${x.startSeconds!=null?`${U.time(x.startSeconds)}–${U.time(x.endSeconds)}`:`characters ${U.num(x.startChar)}–${U.num(x.endChar)}`}<br>Speaker attribution: ${U.esc(x.speakerAttribution||'unknown')}. ${U.esc(U.human(x.boundaryStatus||'question_answer_turns_unsegmented'))}.</p><details><summary>Inspect provenance and candidate limits</summary><p>Prompt family: ${U.esc(x.promptFamily)}. Question form: ${U.esc(x.questionForm)}. Answer scope: ${U.esc(x.answerScope)}. Human validated: ${x.humanValidated?'yes':'no'}.</p><p class="hash">Source text SHA-256 ${U.esc(x.sourceTranscriptSha256)}</p><p class="hash">Candidate ID ${U.esc(x.candidateId)}</p></details></article>`}).join('')}</div>${q.length?'':U.empty('No candidate paraphrases match these source and question filters. This is not evidence that the source contains no questions.')}<div class="pager"><span>Page ${S.qaPage} / ${pageCount}</span><div><button class="secondary" data-action="qa-prev"${S.qaPage===1?' disabled':''}>Previous</button><button class="secondary" data-action="qa-next"${S.qaPage===pageCount?' disabled':''}>Next</button></div></div></section>`;
}
function distributionRows(){const d=TX.data.distributions;if(!d)return[];let rows=S.storageFrame==='youtube'?d.youtube?.[S.storageGroup]:(d.sourceStorage?.[S.storageGroup]||[]);return(U.rows(rows)).filter(x=>!S.storageQuery||JSON.stringify(x).toLowerCase().includes(S.storageQuery.toLowerCase()))}
