function storage(){
 const d=TX.data.distributions,a=TX.data.archive?.state;if(!d)return U.heading('Source accounting · distinct populations','Contexts and storage','Inherited YouTube associations, actual publisher-source files and verified local copies are separate accounting frames.')+U.empty('Storage distributions are not bound yet.');
 const isYT=S.storageFrame==='youtube',groups=isYT?[['byPublisherGroup','Inherited publisher groups'],['byRoute','Literal channel/account routes'],['byPractitionerAssociation','Practitioner associations'],['byEntityLabel','Inherited entity labels'],['byPublisherDeclaredCivilization','Publisher-declared civilization labels']]:[['byPublisher','Publisher'],['byPractitionerContext','Practitioner context'],['bySourceContext','Source context'],['byProvider','Provider']];if(!groups.some(([k])=>k===S.storageGroup))S.storageGroup=groups[0][0];
 const rows=distributionRows(),key=isYT?S.storageMetric:'canonical_source_bytes',ranked=[...rows].sort((a,b)=>(b[key]??b.total_bytes??0)-(a[key]??a.total_bytes??0)),metricLabel=isYT?U.human(S.storageMetric):'canonical source bytes';const rowCount=ranked.length,pages=Math.max(1,Math.ceil(rowCount/20));S.storagePage=Math.min(S.storagePage,pages);
 return U.heading('Accounting frames · source labels are not verified voices','Contexts, downloads and storage','Inspect inherited channel associations separately from actual saved source files. Publisher RSS bytes are never assigned to a YouTube route without verified edition equivalence.')+
 `<div class="two-col"><section><h2>Actual managed local archive</h2><p>${a?.actual_local_archive_completed?'Completed and hash-verified':'No completed archive state bound'}: <strong>${U.num(a?.actual_local_files)} files</strong> · ${U.bytes(a?.actual_local_bytes)}. ${a?.actual_local_archive_completed?'These are independent managed-workspace copies, not merely a transfer plan;99source artifacts plus101metadata files.':''}</p><p class="caption">Drive uploads by this workflow: ${U.num(a?.actual_drive_uploaded_files)}. A Drive connection is ${a?.drive_connection_available_in_environment?'visible':'not visible'} in this environment despite the user-reported connection. Environment retention guaranteed: ${a?.environment_retention_guaranteed?'yes':'no'}. Not a chat attachment or a durable Drive backup. Raw local paths are not browser download links.</p>${U.artifact('archive-state.json','Exact local archive state')}</section><section><h2>YouTube collection remains separate</h2><p><strong>0 saved YouTube videos, audio or captions</strong> in the recorded worker outputs. Indexed IDs and policy selections describe metadata scope, not completed downloads.</p><p class="caption">Full channel lifetime counts and all reposter coverage remain unknown. Literal routes can be aliases; practitioner/entity/civilization associations overlap.</p><a href="../research/#harvest">Open the access, selection and runner ledger →</a></section></div>`+
 `<section class="section"><form id="storage-filter" class="toolbar"><label>Accounting frame<select name="storageFrame">${U.option('youtube','Inherited YouTube metadata',S.storageFrame)}${U.option('source','Actual canonical source files',S.storageFrame)}</select></label><label>Group by<select name="storageGroup">${groups.map(([k,l])=>U.option(k,l,S.storageGroup)).join('')}</select></label>${isYT?`<label>Measure<select name="storageMetric">${[['selected_ids','Planned selected upload IDs'],['indexed_ids','Indexed upload IDs'],['eligible_ids','Metadata-eligible upload IDs'],['unconflicted_measured_upload_seconds','Known upload seconds (unconflicted)'],['youtube_downloaded_video_files','Actual YouTube video files'],['youtube_downloaded_caption_files','Actual YouTube caption files'],['youtube_downloaded_bytes','Actual YouTube bytes']].map(([k,l])=>U.option(k,l,S.storageMetric)).join('')}</select></label>`:''}<label>Group label / route search<input type="search" name="storageQuery" value="${U.esc(S.storageQuery)}" placeholder="Search source associations"></label><button type="submit">Apply accounting filters</button><button type="button" class="secondary" data-action="export-storage">Export matching group metadata</button></form>${isYT&&d.attributionCoverage?.[S.storageGroup]?`<div class="status"><strong>Full inventory attribution coverage</strong><span>${U.num(d.attributionCoverage[S.storageGroup].assignedUniqueIds)} / ${U.num(d.attributionCoverage[S.storageGroup].indexedDenominator)} IDs have an inherited association; ${U.num(d.attributionCoverage[S.storageGroup].unassignedUniqueIds)} are unassigned. ${U.num(d.attributionCoverage[S.storageGroup].groupMemberships)} memberships include ${U.num(d.attributionCoverage[S.storageGroup].extraOverlappingMemberships)} extra overlapping assignments. Missing attribution does not mean no identity; this coverage describes the full frame, before label search.</span></div>`:''}<p class="caption">${U.num(rows.length)} matching ${isYT?'inventory association':'assigned canonical-file accounting'} rows. ${isYT?'Group memberships overlap; do not sum rows as unique videos. Publisher-declared civilizations are inherited labels, distinct from dictionary mentions in transcript text.':'Each source/provider grouping is an assigned file partition of the99canonical artifacts. Group classifications are catalog context, not speaker verification; sidecar/archive-copy counts are a separate layer.'}</p>${ranked.length&&ranked.some(r=>(r[key]??r.total_bytes??0)>0)?TX.chart.bars(ranked.slice(0,15).map(r=>({label:labelOf(r),value:r[key]??r.total_bytes??0,digits:0,display:!isYT||key.endsWith('_bytes')?U.bytes(r[key]??r.total_bytes??0):U.num(r[key]??r.total_bytes??0)}))):U.empty('All recorded values are zero for this measure, or no group matches. No completed downloads are inferred from inventory rows.')}<p class="caption">Ranking measure: ${U.esc(metricLabel)}. ${ranked.length>15?'Plot shows the top 15 matching rows; table/export retain the full matching population.':''}</p>${isYT?U.table(['Source association','Indexed IDs','Eligible IDs','Selected IDs','Known upload hours','Actual YouTube video/caption files · bytes'],ranked.slice((S.storagePage-1)*20,S.storagePage*20).map(r=>[U.esc(labelOf(r))+(r.url?`<small>${U.sourceLink(r.url,'Original account route')}</small>`:''),U.num(r.indexed_ids),U.num(r.eligible_ids),U.num(r.selected_ids),U.num(r.unconflicted_measured_upload_seconds/3600,2)+`<small>${U.num(r.measured_upload_ids)} measured IDs; unknown/conflicting durations excluded</small>`,`${U.num(r.youtube_downloaded_video_files)} / ${U.num(r.youtube_downloaded_caption_files)} · ${U.num(r.youtube_downloaded_bytes)}`])):U.table(['Source accounting group','Canonical artifacts','Bytes','Audio recordings / duration'],ranked.slice((S.storagePage-1)*20,S.storagePage*20).map(r=>[U.esc(labelOf(r))+`<small>${U.esc(Object.entries(r.artifacts_by_kind||{}).map(([k,n])=>k+': '+n).join(' · '))}</small>`,U.num(r.canonical_source_artifacts),U.num(r.canonical_source_bytes),`${U.num(r.source_recordings)} / ${U.num((r.recorded_audio_seconds)/3600,2)} h`]))}<div class="pager"><span>Page ${S.storagePage} / ${pages}</span><div><button class="secondary" data-action="storage-prev"${S.storagePage===1?' disabled':''}>Previous</button><button class="secondary" data-action="storage-next"${S.storagePage===pages?' disabled':''}>Next</button></div></div></section>`;
}
function methods(){const a=TX.data.analysis,protocol=TX.data.protocol,files=TX.data.artifacts;return U.heading('Reproducible derived evidence','Sources and methods','Download source-bound numerical results, candidate paraphrases and manuscript artifacts. Raw full transcripts and recordings remain outside public Git and Pages.')+
 `<section class="section"><h2>Definitions that shape the plots</h2>${U.table(['Measure','Definition'],[['Common analytical tokens',U.esc(protocol.tokenizer||'Common regex tokenizer, distinct from receipt word counts')],['TF-IDF',U.esc(JSON.stringify(protocol.tfidf||{}))],['Topics',U.esc(JSON.stringify(protocol.topics||{}))],['Networks',U.esc(JSON.stringify(protocol.networks||{}))],['Rates',U.esc(protocol.rates||'Pattern occurrences per1,000 common tokens')],['Qualitative reading','AI interpretations of sampled support windows; public question and answer wording is paraphrased. No human-coded accuracy or verified question/answer turn segmentation.']])}<h3>Interpretive limits</h3><ul>${(a.limits||[]).map(x=>`<li>${U.esc(x)}</li>`).join('')}</ul></section><section class="section"><h2>Sensitivity diagnostics</h2>${U.table(['Diagnostic','Observed lexical result / scope'],a.sensitivities.map(x=>[U.esc(U.human(x.name)),U.esc(JSON.stringify(Object.fromEntries(Object.entries(x).filter(([k])=>!['records','excludedTokens','name'].includes(k)))))]))}<details><summary>Inspect ASR KMeans candidates</summary>${U.table(['k','Cosine silhouette','Mean seed-adjusted Rand index'],a.clusters.candidates.map(x=>[U.num(x.k),U.num(x.cosineSilhouette,4),U.num(x.seedAriMean,4)]))}</details></section><section class="section"><div class="section-head"><h2>Standalone research figures</h2><p>These are full-fit exported figures. Source filters in the explorer do not alter them. Download vector/PDF versions for inspection.</p></div><div class="figure-grid">${(a.figures||[]).map(f=>`<figure><img loading="lazy" src="${U.esc(f.paths.find(p=>p.endsWith('.png')))}" alt="${U.esc(U.human(f.id))}"><figcaption>${U.esc(f.caption)}<br>${f.paths.filter(p=>!p.endsWith('.png')).map(p=>U.artifact(p,p.endsWith('.pdf')?'PDF':'SVG')).join(' · ')}</figcaption></figure>`).join('')}</div></section><section class="section"><h2>Source metadata and downloads</h2><ul class="artifacts">${files.map(f=>`<li>${U.artifact(f.path,f.label)}<small>${U.num(f.bytes)} bytes · ${U.esc(f.kind)}</small><div class="hash">SHA-256 ${U.esc(f.sha256)}</div></li>`).join('')}</ul></section>`}
function render({focus=false}={}){
 const view=location.hash.slice(1);S.view=names[view]?view:'overview';scope();document.title=names[S.view]+' · Transcript study · 23 October 2026';document.querySelectorAll('.view-nav a').forEach(a=>a.toggleAttribute('aria-current',a.hash==='#'+S.view));document.querySelectorAll('.view-nav a[aria-current]').forEach(a=>a.setAttribute('aria-current','page'));
 $('#app').innerHTML=(TX.data.releaseStatus!=='final'?`<div class="notice"><strong>Local review candidate</strong>This source-backed candidate is being reviewed before publication. It does not replace the preserved scientific release.</div>`:'')+({overview,maps,reading,storage,methods})[S.view]();if(focus)$('#content').focus();$('#live-status').textContent=names[S.view]+'. '+(['storage','methods'].includes(S.view)?'Source accounting and methods use their own stated populations.':TX.currentDocs().length+' selected documents.');
}
function resetSource(corpus){S.corpus=corpus;S.publisher='all';S.context='all';S.query='';S.topic='all';S.selected=null;S.qaPage=1;S.qaKind='all';S.qaFamily='all';S.qaQuery='';S.overlay=false}
document.addEventListener('submit',e=>{if(e.target.id==='scope-form'){e.preventDefault();const f=new FormData(e.target);S.publisher=f.get('publisher');S.context=f.get('context');S.query=f.get('query').trim();S.qaPage=1;S.selected=null;render();$('#scope-form button').focus({preventScroll:true})}if(e.target.id==='qa-filter'){e.preventDefault();const f=new FormData(e.target);S.qaKind=f.get('qaKind');S.qaFamily=f.get('qaFamily');S.qaQuery=f.get('qaQuery').trim();S.qaPage=1;render();$('#qa-filter button[type=submit]').focus({preventScroll:true})}if(e.target.id==='storage-filter'){e.preventDefault();const f=new FormData(e.target);S.storageFrame=f.get('storageFrame');S.storageGroup=f.get('storageGroup');S.storageMetric=f.get('storageMetric')||'canonical_source_bytes';S.storageQuery=f.get('storageQuery').trim();S.storagePage=1;render();$('#storage-filter button[type=submit]').focus({preventScroll:true})}});
document.addEventListener('input',e=>{if(e.target.name==='threshold'){$('#threshold-output').textContent=Number(e.target.value).toFixed(2);S.threshold=+e.target.value}});
document.addEventListener('change',e=>{const n=e.target.name;if(n==='corpus'){resetSource(e.target.value);render();$('#scope-form [name=corpus]').focus()}else if(e.target.closest('#map-controls')){S[n]=e.target.type==='checkbox'?e.target.checked:n==='threshold'?+e.target.value:e.target.value;render();document.querySelector('#map-controls [name="'+n+'"]')?.focus()}else if(n==='storageFrame'){S.storageFrame=e.target.value;S.storageGroup=S.storageFrame==='youtube'?'byPublisherGroup':'byPublisher';S.storageMetric=S.storageFrame==='youtube'?'selected_ids':'canonical_source_bytes';S.storagePage=1;render();$('#storage-filter [name=storageFrame]').focus()}});
function selectNode(id){S.selected=id;render();document.querySelector('[data-node="'+CSS.escape(id)+'"]')?.focus();$('#live-status').textContent='Selected '+TX.source(id)?.shortId+'. Source details and adjacent lexical pairs are in the inspector.'}
document.addEventListener('click',e=>{const source=e.target.closest('[data-source]');if(source){TX.sourceDetail(source.dataset.source);return}const node=e.target.closest('[data-node]');if(node){selectNode(node.dataset.node);return}const map=e.target.closest('[data-map]');if(map){S.map=map.dataset.map;S.topic='all';S.zoom=1;render();document.querySelector('[data-map="'+S.map+'"]').focus();return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='close-dialog')$('#source-dialog').close();if(action==='reset-source-filters'){resetSource(S.corpus);render();$('#scope-form [name=corpus]').focus()}if(action==='export-sources')TX.export('transcript-sources-filtered.json',TX.visibleDocs());if(action==='export-edges')TX.export('transcript-lexical-pairs-filtered.json',TX.edges());if(action==='export-terms')TX.export('transcript-tfidf-filtered.json',termRows(TX.currentDocs()));if(action==='export-qa')TX.export('transcript-qa-candidates-filtered.json',qaRecords());if(action==='export-storage')TX.export('source-storage-groups-filtered.json',distributionRows());if(['zoom-in','zoom-out','zoom-reset'].includes(action)){S.zoom=action==='zoom-reset'?1:Math.max(.6,Math.min(2.5,S.zoom+(action==='zoom-in'?.2:-.2)));render();document.querySelector('[data-action="'+action+'"]').focus()}if(action==='qa-next'||action==='qa-prev'){S.qaPage+=action==='qa-next'?1:-1;render()}if(action==='storage-next'||action==='storage-prev'){S.storagePage+=action==='storage-next'?1:-1;render()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-node]')){e.preventDefault();selectNode(e.target.dataset.node)}});
window.addEventListener('hashchange',()=>render({focus:true}));
fetch('data.json').then(r=>{if(!r.ok)throw Error('Metadata request returned HTTP '+r.status);return r.json()}).then(data=>{TX.data=data;render()}).catch(e=>{$('#app').innerHTML=U.heading('Source data unavailable','The study metadata could not load',U.esc(e.message))+`<p>Reload this published page or inspect the <a href="data.json">data snapshot</a>. No unavailable result is replaced with sample data.</p>`});
